func (ec *ExecutionContext) applyLifecycleSubstitutions(ctx context.Context, template string) string {
	if !strings.Contains(template, lifecycleSubstitutionPrefix) {
		return template
	}
	if ec.Lifecycle == nil || ec.EntityID == "" {
		// Manager not wired or no entity → surviving tokens trip
		// the unresolved-template warning; intentional loud-fail.
		return template
	}

	participant, err := ec.lookupLifecycleParticipant(ctx)
	if err != nil {
		// Negative lookup is cached on ec; no need to re-log per
		// substitution call. The unresolved-template warning will
		// surface the surviving tokens once per substitution call,
		// which is the operator-visible signal.
		return template
	}

	// Two-pass substitution to prevent the prefix-superset
	// corruption class: surviving longer-suffix tokens are protected
	// with NUL-sentinel placeholders during the shorter-suffix
	// substitution pass, then restored. Without this, a surviving
	// `$entity.lifecycle.workflow_def` would morph into
	// `$entity.lifecycle.<workflowName>_def` when the `.workflow`
	// rule fires, misleading operators hunting for a token they
	// never wrote.
	const placeholderPrefix = "\x00__LIFECYCLE_SURVIVED_"
	const placeholderSuffix = "__\x00"
	result := template
	survived := make(map[string]string) // suffix → placeholder used
	for _, rule := range lifecycleSubstitutionRules {
		token := lifecycleSubstitutionPrefix + rule.suffix
		if !strings.Contains(result, token) {
			continue
		}
		value, ok := rule.resolve(ec, participant)
		if ok {
			result = strings.ReplaceAll(result, token, value)
			continue
		}
		// Resolve failed → protect the surviving token with a
		// per-suffix placeholder so subsequent shorter-suffix rules
		// don't shred it. Restore at the end.
		placeholder := placeholderPrefix + rule.suffix + placeholderSuffix
		result = strings.ReplaceAll(result, token, placeholder)
		survived[rule.suffix] = placeholder
	}
	for suffix, placeholder := range survived {
		result = strings.ReplaceAll(result, placeholder, lifecycleSubstitutionPrefix+suffix)
	}
	return result
}

func (index *projectionTargetIndex) resolve(contract, group, predicate string) (projectionTarget, error) {
	if strings.TrimSpace(contract) == "" {
		return projectionTarget{}, fmt.Errorf("projection_contract is required")
	}
	if strings.TrimSpace(group) == "" {
		return projectionTarget{}, fmt.Errorf("projection_group is required")
	}
	if strings.TrimSpace(predicate) == "" {
		return projectionTarget{}, fmt.Errorf("predicate is required")
	}
	if strings.Contains(predicate, "$") {
		return projectionTarget{}, fmt.Errorf("predicate %q must be a literal", predicate)
	}
	if index == nil {
		return projectionTarget{}, fmt.Errorf("projection target index is not initialized")
	}
	groups, ok := index.contracts[contract]
	if !ok {
		return projectionTarget{}, fmt.Errorf("unknown projection contract %q", contract)
	}
	targetGroup, ok := groups[group]
	if !ok {
		return projectionTarget{}, fmt.Errorf(
			"projection contract %q has no named projection group %q",
			contract,
			group,
		)
	}
	if targetGroup.mode != projection.ModeReconcile {
		return projectionTarget{}, fmt.Errorf(
			"projection group %q in contract %q uses mode %q, not reconcile",
			group,
			contract,
			targetGroup.mode,
		)
	}
	if _, ok := targetGroup.predicates[predicate]; !ok {
		return projectionTarget{}, fmt.Errorf(
			"predicate %q is outside projection contract %q group %q",
			predicate,
			contract,
			group,
		)
	}
	return projectionTarget{
		Contract:   contract,
		Group:      group,
		Predicate:  predicate,
		Predicates: append([]string(nil), targetGroup.ordered...),
	}, nil
}

type minimalProjectionContract struct {
	pattern         string
	patternLocation string
	groups          map[string]map[string]struct{}
}

func applyCallerSubstitutions(template string, cc *CallerContext) string {
	if cc == nil {
		return template
	}
	result := template
	result = strings.ReplaceAll(result, "$caller.id", cc.ID)
	result = strings.ReplaceAll(result, "$caller.role", cc.Role)
	result = strings.ReplaceAll(result, "$caller.org", cc.Org)
	return result
}

func (e *StatefulEvaluator) evaluateWhen(
	ctx context.Context,
	conditions []expression.ConditionExpression,
	entity *gtypes.EntityState,
	stateFields expression.StateFields,
	messageFields expression.MessageFields,
) (bool, error) {
	// #149: substitute $-prefixed string Values in conditions before
	// evaluation. evaluateWhen runs per-action when-clauses; the same
	// substitution semantics that apply to top-level conditions apply
	// here.
	resolvedID := ""
	if entity != nil {
		resolvedID = entity.ID
	}
	ec := &ExecutionContext{
		EntityID:    resolvedID,
		Entity:      entity,
		MessageData: map[string]any(messageFields),
		Lifecycle:   e.lifecycleManager,
	}
	expr := expression.LogicalExpression{
		Conditions: SubstituteConditionValues(ctx, conditions, ec),
		Logic:      expression.LogicAnd,
	}
	return e.exprEvaluator.EvaluateWithStateAndMessage(entity, stateFields, messageFields, expr)
}

func (s *CronScheduler) submitDispatch(run func(context.Context) error) error {
	err := s.dispatch.submit(run)
	switch {
	case errors.Is(err, errLaneAdmissionClosed):
		return errors.New("cron scheduler: dispatch admission is closed")
	case errors.Is(err, errLaneEnded):
		return errors.New("cron scheduler: dispatcher stopped")
	}
	return err
}

func populateLifecycleStateFields(ctx context.Context, manager LifecycleManager, entityID string, fields expression.StateFields) error {
	if manager == nil || entityID == "" || fields == nil {
		return nil
	}
	p, err := manager.LookupByEntityID(ctx, entityID)
	if err != nil {
		return err
	}
	fields["$entity.lifecycle.phase"] = p.Phase()
	fields["$entity.lifecycle.terminal"] = p.IsTerminal()
	fields["$entity.lifecycle.workflow"] = p.Workflow()
	return nil
}

func (s *CronScheduler) Stop(ctx context.Context) error {
	if ctx == nil {
		return errors.New("cron scheduler: Stop requires a non-nil context")
	}
	var cancel context.CancelFunc
	for {
		s.lifecycleMu.Lock()
		if s.startDone != nil {
			startDone := s.startDone
			s.lifecycleMu.Unlock()
			select {
			case <-startDone:
				continue
			case <-ctx.Done():
				return ctx.Err()
			}
		}
		if s.stopped {
			s.lifecycleMu.Unlock()
			return nil
		}
		if s.stopping {
			s.lifecycleMu.Unlock()
			return errs.WrapTransient(errors.New("stop already in progress"), "CronScheduler", "Stop", "concurrent Stop")
		}
		s.lifecycleUsed = true
		s.registerFence = true
		s.stopping = true
		cancel = s.cancel
		s.lifecycleMu.Unlock()
		break
	}

	barrier := s.dispatch.fence()
	nativeStop := s.cron.Stop()
	s.metrics.recordSchedulerRunning(false)
	s.logger.Info("Cron scheduler stopping")
	err := s.awaitStop(ctx, nativeStop.Done(), barrier, cancel)

	s.lifecycleMu.Lock()
	s.stopping = false
	s.stopped = err == nil
	s.lifecycleMu.Unlock()
	return err
}

var cronParser = cronlib.NewParser(
	cronlib.Minute | cronlib.Hour | cronlib.Dom | cronlib.Month | cronlib.Dow | cronlib.Descriptor,
)

func lookupTripleObjectTyped(entity *gtypes.EntityState, predicate string) (any, bool) {
	if entity == nil {
		return nil, false
	}
	for _, triple := range entity.Triples {
		if triple.Predicate == predicate {
			return triple.Object, true
		}
	}
	return nil, false
}

func (e *StatefulEvaluator) reEvaluateTransitions(
	ctx context.Context,
	ruleDef Definition,
	entityID string,
	entity *gtypes.EntityState,
	prevState MatchState,
	currentlyMatching bool,
) bool {
	if !hasTransitionConditions(ruleDef) || entity == nil {
		return currentlyMatching
	}

	prevFields := expression.StateFields{}
	for field, prevValue := range prevState.FieldValues {
		prevFields["$prev."+field] = prevValue
	}
	// ADR-047: surface $entity.lifecycle.* keys to the evaluator on
	// the transition-re-eval path so a rule conditioning on phase
	// can fire its `On: enter/exit` transitions correctly.
	PopulateLifecycleStateFields(ctx, e.lifecycleManager, entityID, prevFields)

	// #149: substitute $-prefixed string Values in conditions
	// against the entity before evaluation. Without this, a condition
	// `value: "$entity.triple.foo.length"` reaches the operator as
	// the literal template and coerce-errors at runtime.
	ec := &ExecutionContext{EntityID: entityID, Entity: entity, Lifecycle: e.lifecycleManager}
	expr := expression.LogicalExpression{
		Conditions: SubstituteConditionValues(ctx, ruleDef.Conditions, ec),
		Logic:      ruleDef.Logic,
	}
	if expr.Logic == "" {
		expr.Logic = expression.LogicAnd
	}
	match, err := e.exprEvaluator.EvaluateWithStateAndMessage(entity, prevFields, nil, expr)
	if err != nil {
		e.logger.Warn("Failed to re-evaluate transition conditions",
			"rule_id", ruleDef.ID,
			"entity_id", entityID,
			"error", err)
		return currentlyMatching
	}
	return match
}

func buildProjectionTargetIndex(contracts []projection.Contract) (*projectionTargetIndex, error) {
	index := &projectionTargetIndex{
		contracts: make(map[string]map[string]projectionTargetGroup, len(contracts)),
	}
	if len(contracts) == 0 {
		return index, nil
	}
	copies := cloneProjectionContracts(contracts)
	if err := projection.ValidateContracts(copies); err != nil {
		return nil, fmt.Errorf("validate projection contracts: %w", err)
	}
	for _, contract := range copies {
		groups := make(map[string]projectionTargetGroup, len(contract.Groups))
		for _, group := range contract.Groups {
			if group.Name == "" {
				continue
			}
			predicates := make(map[string]struct{}, len(group.Predicates))
			ordered := append([]string(nil), group.Predicates...)
			sort.Strings(ordered)
			for _, predicate := range ordered {
				predicates[predicate] = struct{}{}
			}
			groups[group.Name] = projectionTargetGroup{
				mode:       group.Mode,
				predicates: predicates,
				ordered:    ordered,
			}
		}
		index.contracts[contract.Name] = groups
	}
	return index, nil
}

func createAndRegisterCronMetrics(registry *metric.MetricsRegistry) *cronMetrics {
	const (
		namespace = "semstreams"
		subsystem = "cron"
	)
	m := &cronMetrics{
		firesTotal: prometheus.NewCounterVec(prometheus.CounterOpts{
			Namespace: namespace,
			Subsystem: subsystem,
			Name:      "rule_fires_total",
			Help:      "Cron rule fire attempts by rule and outcome (success/error/panic/cooldown_skipped/inflight_skipped/denied)",
		}, []string{"rule_id", "status"}),

		fireDurationSeconds: prometheus.NewHistogramVec(prometheus.HistogramOpts{
			Namespace: namespace,
			Subsystem: subsystem,
			Name:      "rule_fire_duration_seconds",
			Help:      "Action-dispatch latency per cron rule fire",
			// 1ms to ~16s — covers fast publish actions through slow
			// publish_agent dispatches that include LLM round-trips.
			Buckets: prometheus.ExponentialBuckets(0.001, 2, 14),
		}, []string{"rule_id"}),

		registered: prometheus.NewGauge(prometheus.GaugeOpts{
			Namespace: namespace,
			Subsystem: subsystem,
			Name:      "rule_registered",
			Help:      "Number of cron rules currently registered with the scheduler",
		}),

		missedFiresTotal: prometheus.NewCounterVec(prometheus.CounterOpts{
			Namespace: namespace,
			Subsystem: subsystem,
			Name:      "rule_missed_fires_total",
			Help:      "Cron rule missed fires detected on scheduler restart (log-only policy; not replayed)",
		}, []string{"rule_id"}),

		missedFiresCappedTotal: prometheus.NewCounterVec(prometheus.CounterOpts{
			Namespace: namespace,
			Subsystem: subsystem,
			Name:      "rule_missed_fires_capped_total",
			Help:      "Cron rules whose missed-fire detection hit the bounded cap (100) at restart — long downtime indicator",
		}, []string{"rule_id"}),

		nextFireTimestampSecs: prometheus.NewGaugeVec(prometheus.GaugeOpts{
			Namespace: namespace,
			Subsystem: subsystem,
			Name:      "rule_next_fire_timestamp_seconds",
			Help:      "Unix epoch (seconds) of the next scheduled fire per cron rule",
		}, []string{"rule_id"}),

		schedulerRunning: prometheus.NewGauge(prometheus.GaugeOpts{
			Namespace: namespace,
			Subsystem: subsystem,
			Name:      "scheduler_running",
			Help:      "1 when the cron scheduler is started and ticking, 0 otherwise",
		}),
	}

	if registry != nil {
		_ = registry.RegisterCounterVec(subsystem, "rule_fires_total", m.firesTotal)
		_ = registry.RegisterHistogramVec(subsystem, "rule_fire_duration_seconds", m.fireDurationSeconds)
		_ = registry.RegisterGauge(subsystem, "rule_registered", m.registered)
		_ = registry.RegisterCounterVec(subsystem, "rule_missed_fires_total", m.missedFiresTotal)
		_ = registry.RegisterCounterVec(subsystem, "rule_missed_fires_capped_total", m.missedFiresCappedTotal)
		_ = registry.RegisterGaugeVec(subsystem, "rule_next_fire_timestamp_seconds", m.nextFireTimestampSecs)
		_ = registry.RegisterGauge(subsystem, "scheduler_running", m.schedulerRunning)
	} else {
		_ = prometheus.DefaultRegisterer.Register(m.firesTotal)
		_ = prometheus.DefaultRegisterer.Register(m.fireDurationSeconds)
		_ = prometheus.DefaultRegisterer.Register(m.registered)
		_ = prometheus.DefaultRegisterer.Register(m.missedFiresTotal)
		_ = prometheus.DefaultRegisterer.Register(m.missedFiresCappedTotal)
		_ = prometheus.DefaultRegisterer.Register(m.nextFireTimestampSecs)
		_ = prometheus.DefaultRegisterer.Register(m.schedulerRunning)
	}
	return m
}

type Evaluation struct {
	Rule              Definition
	EntityID          string
	RelatedID         string // "" for single-entity rules
	CurrentlyMatching bool
	Entity            *gtypes.EntityState // nil for message-path rules
	Related           *gtypes.EntityState // nil for single-entity or message-path
	Revision          uint64              // KV revision that triggered this evaluation; 0 if unknown
	Bootstrap         bool                // true during watcher initial-state replay

	// MessageData carries the payload of the inbound message that
	// triggered evaluation, as a generic map for dotted-path access.
	// Populated by `evaluateRulesForMessage` from the payload's declared
	// message.RuleReadable fields (see `ruleFields`) for message-path
	// (NATS-subscribed) rules. Nil for entity-state-driven and cron-fired
	// evaluations. Plumbed through to `ExecutionContext.MessageData` so
	// `$message.*` substitution can resolve.
	MessageData map[string]any
}

func applyScheduleSubstitutions(template string, sc *ScheduleContext) string {
	if sc == nil {
		return template
	}
	result := template
	result = strings.ReplaceAll(result, "$schedule.id", sc.ID)
	result = strings.ReplaceAll(result, "$schedule.spec", sc.Spec)

	var lastFired string
	if !sc.LastFiredAt.IsZero() {
		lastFired = sc.LastFiredAt.UTC().Format(time.RFC3339)
	}
	result = strings.ReplaceAll(result, "$schedule.last_fired_at", lastFired)

	return result
}

type ScheduleContext struct {
	// ID is the firing rule's stable identifier — same value as
	// Definition.ID and CronRule.ID. Always non-empty for a cron fire.
	ID string

	// Spec is the cron expression as the rule was registered with it.
	// Captured at fire time so a hot-reload that changes the schedule
	// doesn't retroactively alter substitution output for in-flight
	// dispatches. Always non-empty for a cron fire.
	Spec string

	// LastFiredAt is the wallclock of the most recent successful fire
	// before this one. Zero value (time.IsZero) on the first fire of
	// a freshly-registered rule, before any persisted record exists.
	// The substitution renders zero as the empty string so authors can
	// detect first-fire via `len("$schedule.last_fired_at") == 0` in
	// downstream conditional templates.
	LastFiredAt time.Time
}

func (st *StateTracker) DeleteAllForEntity(ctx context.Context, entityID string) error {
	// Handle nil bucket (for tests)
	if st.bucket == nil {
		return fmt.Errorf("state tracker bucket is nil")
	}

	// List all keys and delete those containing the entityID
	keys, err := st.bucket.Keys(ctx)
	if err != nil {
		return fmt.Errorf("list rule state keys: %w", err)
	}

	for _, key := range keys {
		if stateKeyBelongsToEntity(key, entityID) {
			if err := st.bucket.Delete(ctx, key); err != nil && !errors.Is(err, jetstream.ErrKeyNotFound) {
				st.logger.Warn("Failed to delete rule state",
					"key", key,
					"entity_id", entityID,
					"error", err)
			}
		}
	}

	return nil
}

func (s *CronScheduler) fire(ruleID string) {
	if s.ready != nil && !s.ready() {
		return
	}
	s.mu.Lock()
	entry, ok := s.entries[ruleID]
	s.mu.Unlock()
	if !ok {
		// Rule was deregistered between the tick scheduling and now;
		// dropping silently is correct — robfig will not deliver future
		// ticks for the removed entry.
		return
	}

	tick := entry.tickCount.Add(1)

	// FireEveryN gate — every Nth tick fires actions; intermediate ticks
	// are noop'd. N=0 and N=1 both mean "fire every tick" (matches
	// FireEveryNEvents semantics on expression rules).
	if n := entry.rule.FireEveryN(); n > 1 {
		if tick%int64(n) != 0 {
			s.logger.Debug("Cron rule tick skipped (every-N gate)",
				"rule_id", ruleID,
				"tick", tick,
				"every", n)
			return
		}
	}

	// Capture the previous fire timestamp once: the cooldown gate
	// reads it for its check, and the ScheduleContext built for
	// substitution below uses it as `$schedule.last_fired_at`. Reading
	// once keeps both views consistent with each other (no mid-fire
	// race where cooldown sees the prior timestamp but substitution
	// sees `time.Now()` because another fire snuck in).
	previousFiredNanos := entry.lastFiredNanos.Load()

	// Cooldown gate — skip if the previous fire's wallclock is too
	// recent. Defends against the operator-error case of a cron expression
	// that ticks faster than actions complete on average.
	if cooldown := entry.rule.Cooldown(); cooldown > 0 {
		if previousFiredNanos > 0 && time.Since(time.Unix(0, previousFiredNanos)) < cooldown {
			s.metrics.recordFire(ruleID, cronFireStatusCooldownSkipped, 0)
			s.logger.Debug("Cron rule fire skipped (cooldown)",
				"rule_id", ruleID,
				"cooldown", cooldown)
			return
		}
	}

	// Inflight guard — skip if a previous fire is still running. The CAS
	// is the source of truth for "currently dispatching"; cooldown above
	// is wallclock-based and orthogonal. Both are needed: cooldown handles
	// fast-cycling slow rules, inflight handles a fire that exceeded its
	// own period. Distinct status from cooldown_skipped because the
	// operator action is different: cooldown_skipped means "configured
	// throttling worked", inflight_skipped means "actions are slower
	// than the schedule, configure a cooldown or speed them up".
	if !entry.inflight.CompareAndSwap(false, true) {
		s.metrics.recordFire(ruleID, cronFireStatusInflightSkipped, 0)
		s.logger.Warn("Cron rule fire skipped (previous fire still running)",
			"rule_id", ruleID)
		return
	}
	defer entry.inflight.Store(false)

	if err := s.submitDispatch(func(ctx context.Context) error {
		s.dispatchAndRecord(ctx, ruleID, entry, previousFiredNanos)
		return nil
	}); err != nil {
		s.logger.Debug("Cron rule fire rejected by runtime coordinator", "rule_id", ruleID, "error", err)
	}
}

func (m *cronMetrics) clearNextFire(ruleID string) {
	if m == nil {
		return
	}
	m.nextFireTimestampSecs.DeleteLabelValues(ruleID)
}

func (st *ScheduleTracker) RecordFire(ctx context.Context, ruleID, scheduleSpec string, firedAt time.Time) error {
	if ruleID == "" {
		return fmt.Errorf("rule ID cannot be empty")
	}
	if st.bucket == nil {
		return fmt.Errorf("schedule tracker bucket is nil")
	}

	rec := LastFireRecord{
		RuleID:       ruleID,
		ScheduleSpec: scheduleSpec,
		LastFiredAt:  firedAt.UTC(),
	}
	data, err := json.Marshal(rec)
	if err != nil {
		return fmt.Errorf("marshal schedule record: %w", err)
	}
	if _, err := st.bucket.Put(ctx, scheduleKey(ruleID), data); err != nil {
		return fmt.Errorf("put schedule record: %w", err)
	}
	return nil
}

func (e *StatefulEvaluator) SetLifecycleManager(m LifecycleManager) {
	e.lifecycleManager = m
}

type StateTracker struct {
	bucket jetstream.KeyValue
	logger *slog.Logger
}

func (e *StatefulEvaluator) Evaluate(ctx context.Context, ev Evaluation) (Transition, error) {
	entityKey := ev.entityKey()

	prevState, err := e.stateTracker.Get(ctx, ev.Rule.ID, entityKey)
	wasMatching := false
	hadPrevState := false
	if err != nil {
		if !errors.Is(err, ErrStateNotFound) {
			return TransitionNone, err
		}
	} else {
		wasMatching = prevState.IsMatching
		hadPrevState = true
	}

	// Durable stale-replay guard: if we've already recorded a transition at or
	// after this revision, the watcher is redelivering (NATS reconnect, consumer
	// resume) or delivering out of order. Skip without firing actions or
	// touching persisted state — the ephemeral ownRevisions map defends the
	// normal self-write path, this field defends across process restarts.
	// Revision==0 (message-path rules) and prev.SourceRevision==0 (old
	// persisted state with no recorded revision) both bypass the check.
	if ev.Revision > 0 && hadPrevState && prevState.SourceRevision >= ev.Revision {
		e.logger.Debug("Skipping stale revision replay",
			"rule_id", ev.Rule.ID,
			"entity_key", entityKey,
			"revision", ev.Revision,
			"prev_source_revision", prevState.SourceRevision)
		return TransitionNone, nil
	}

	// Re-evaluate conditions when the rule has transition operators. The initial
	// match evaluation runs without $prev.* state fields, so transition-operator
	// conditions always return false there; we re-check here with the previous
	// field values available.
	currentlyMatching := e.reEvaluateTransitions(ctx, ev.Rule, ev.EntityID, ev.Entity, prevState, ev.CurrentlyMatching)

	transition := DetectTransition(wasMatching, currentlyMatching)

	// Bootstrap recovery: a persisted matching state that still matches would
	// produce TransitionNone. For rules that opt in, promote to a synthetic
	// Entered so OnRecovery (or OnEnter under RerunOnRecovery) re-fires and the
	// state machine resumes instead of hanging.
	recovering := false
	if ev.Bootstrap && hadPrevState && transition == TransitionNone && currentlyMatching &&
		shouldFireOnRecovery(ev.Rule) {
		transition = TransitionEntered
		recovering = true
	}

	iteration := prevState.Iteration
	if transition == TransitionEntered {
		iteration++
	}

	// Carry per-action firing counts forward across evaluations. Counts
	// persist through both transitions and steady-state re-evaluations
	// so the per-action cap covers the full match-cycle for an entity,
	// not just one transition.
	actionIterations := prevState.ActionIterations
	if actionIterations == nil {
		actionIterations = map[string]int{}
	}

	matchState := &MatchState{
		RuleID:           ev.Rule.ID,
		EntityKey:        entityKey,
		IsMatching:       currentlyMatching,
		LastTransition:   string(transition),
		TransitionAt:     time.Now(),
		LastChecked:      time.Now(),
		Iteration:        iteration,
		MaxIterations:    ev.Rule.MaxIterations,
		SourceRevision:   ev.Revision,
		ActionIterations: actionIterations,
	}

	ec := &ExecutionContext{
		EntityID:    ev.EntityID,
		RelatedID:   ev.RelatedID,
		Entity:      ev.Entity,
		Related:     ev.Related,
		State:       matchState,
		MessageData: ev.MessageData,
		Lifecycle:   e.lifecycleManager,
	}

	stateFields := expression.StateFields{
		"$state.iteration":       iteration,
		"$state.max_iterations":  ev.Rule.MaxIterations,
		"$state.last_transition": string(transition),
	}
	for field, prevValue := range prevState.FieldValues {
		stateFields["$prev."+field] = prevValue
	}
	// $entity.lifecycle.* keys live in the same stateFields map by
	// design (see evaluator.go's prefix-check). No-op when no Manager
	// is wired or the trigger entity isn't lifecycle-managed.
	PopulateLifecycleStateFields(ctx, e.lifecycleManager, ev.EntityID, stateFields)

	actions := e.selectActions(ev.Rule, transition, currentlyMatching, recovering, ev.EntityID, ev.RelatedID, iteration)
	e.runActions(ctx, ev.Rule, ec, actions, ev.Entity, stateFields, expression.MessageFields(ev.MessageData), ev.EntityID, ev.RelatedID)

	matchState.FieldValues = captureTransitionFields(ev.Rule, ev.Entity)

	// Once actions have fired, persisting the state that records them is a
	// durability obligation — the persist runs on a ctx detached from the
	// caller's cancellation (gh#557). A SIGTERM landing mid-evaluation
	// cancels the watcher ctx before Manager.StopAll's drain; aborting THIS
	// write makes bootstrap re-derive a world where the actions never
	// happened: OnRecovery silently never fires for on_recovery-only rules,
	// and OnEnter/OnExit double-fire with a reset iteration cap. Pre-action
	// paths stay cancellable — dropping before actions is a clean drop that
	// bootstrap correctly re-derives.
	persistCtx, cancelPersist := context.WithTimeout(context.WithoutCancel(ctx), statePersistTimeout)
	defer cancelPersist()
	if err := e.stateTracker.Set(persistCtx, *matchState); err != nil {
		e.logger.Warn("Failed to persist rule state",
			"rule_id", ev.Rule.ID,
			"entity_key", entityKey,
			"error", err)
		return transition, err
	}

	return transition, nil
}

