func (s *CronScheduler) awaitStop(
	ctx context.Context,
	nativeDone <-chan struct{},
	barrier <-chan error,
	cancel context.CancelFunc,
) error {
	abandon := func() error {
		if cancel != nil {
			cancel()
		}
		return ctx.Err()
	}
	select {
	case <-nativeDone:
	case <-ctx.Done():
		return abandon()
	}
	select {
	case <-barrier:
	case <-ctx.Done():
		return abandon()
	}
	if cancel != nil {
		cancel()
	}
	if dispatchDone := s.dispatch.done(); dispatchDone != nil {
		select {
		case <-dispatchDone:
		case <-ctx.Done():
			return ctx.Err()
		}
	}
	return nil
}

func captureTransitionFields(ruleDef Definition, entity *gtypes.EntityState) map[string]string {
	if entity == nil {
		return nil
	}

	// Collect field names used in transition conditions
	fields := make(map[string]struct{})
	for _, cond := range ruleDef.Conditions {
		if cond.Operator == expression.OpTransition {
			fields[cond.Field] = struct{}{}
		}
	}
	// Also check When clauses inside actions
	for _, actions := range [][]Action{ruleDef.OnEnter, ruleDef.OnExit, ruleDef.WhileTrue} {
		for _, action := range actions {
			for _, cond := range action.When {
				if cond.Operator == expression.OpTransition {
					fields[cond.Field] = struct{}{}
				}
			}
		}
	}

	if len(fields) == 0 {
		return nil
	}

	// Snapshot current values for tracked fields
	values := make(map[string]string, len(fields))
	for _, triple := range entity.Triples {
		if _, tracked := fields[triple.Predicate]; tracked {
			values[triple.Predicate] = fmt.Sprintf("%v", triple.Object)
		}
	}
	return values
}

func (st *ScheduleTracker) LastFiredAt(ctx context.Context, ruleID string) (LastFireRecord, error) {
	if ruleID == "" {
		return LastFireRecord{}, fmt.Errorf("rule ID cannot be empty")
	}
	if st.bucket == nil {
		return LastFireRecord{}, fmt.Errorf("schedule tracker bucket is nil")
	}

	entry, err := st.bucket.Get(ctx, scheduleKey(ruleID))
	if err != nil {
		if errors.Is(err, jetstream.ErrKeyNotFound) {
			return LastFireRecord{}, ErrScheduleRecordNotFound
		}
		return LastFireRecord{}, fmt.Errorf("get schedule record: %w", err)
	}

	var rec LastFireRecord
	if err := json.Unmarshal(entry.Value(), &rec); err != nil {
		return LastFireRecord{}, fmt.Errorf("unmarshal schedule record: %w", err)
	}
	return rec, nil
}

