func (st *StateTracker) Get(ctx context.Context, ruleID, entityKey string) (MatchState, error) {
	// Validate inputs
	if ruleID == "" {
		return MatchState{}, fmt.Errorf("rule ID cannot be empty")
	}
	if entityKey == "" {
		return MatchState{}, fmt.Errorf("entity key cannot be empty")
	}

	// Handle nil bucket (for tests)
	if st.bucket == nil {
		return MatchState{}, fmt.Errorf("state tracker bucket is nil")
	}

	key := buildStateKey(ruleID, entityKey)

	entry, err := st.bucket.Get(ctx, key)
	if err != nil {
		if errors.Is(err, jetstream.ErrKeyNotFound) {
			return MatchState{}, ErrStateNotFound
		}
		return MatchState{}, fmt.Errorf("get rule state: %w", err)
	}

	var state MatchState
	if err := json.Unmarshal(entry.Value(), &state); err != nil {
		return MatchState{}, fmt.Errorf("unmarshal rule state: %w", err)
	}

	return state, nil
}

func ruleFields(msg message.Message) (map[string]any, bool) {
	if msg == nil {
		return nil, false
	}
	payload := msg.Payload()
	if payload == nil {
		return nil, false
	}
	if readable, ok := payload.(message.RuleReadable); ok {
		return readable.RuleFields(), true
	}
	return nil, false
}

func (ec *ExecutionContext) SubstituteVariablesTyped(template string) (any, bool) {
	if len(template) < 2 || template[0] != '$' {
		return nil, false
	}

	if m := typedEntityTripleRe.FindStringSubmatch(template); m != nil {
		return lookupTripleObjectTyped(ec.Entity, m[1])
	}
	if m := typedRelatedTripleRe.FindStringSubmatch(template); m != nil {
		return lookupTripleObjectTyped(ec.Related, m[1])
	}
	if m := typedMessageRe.FindStringSubmatch(template); m != nil {
		if ec.MessageData == nil {
			return nil, false
		}
		return expression.ExtractMessageValue(expression.MessageFields(ec.MessageData), m[1])
	}

	switch template {
	case "$state.iteration":
		if ec.State == nil {
			return nil, false
		}
		return ec.State.Iteration, true
	case "$state.max_iterations":
		if ec.State == nil {
			return nil, false
		}
		return ec.State.MaxIterations, true
	}

	return nil, false
}

