func (ec *ExecutionContext) lookupLifecycleParticipant(ctx context.Context) (lifecycleParticipantSnapshot, error) {
	if ec.lifecycleParticipantCache != nil {
		c := ec.lifecycleParticipantCache
		if c.err != nil {
			return lifecycleParticipantSnapshot{}, c.err
		}
		return participantSnapshot(c.participant), nil
	}
	p, err := ec.Lifecycle.LookupByEntityID(ctx, ec.EntityID)
	ec.lifecycleParticipantCache = &lifecycleLookupResult{
		participant: p,
		err:         err,
	}
	if err != nil {
		return lifecycleParticipantSnapshot{}, err
	}
	return participantSnapshot(p), nil
}

func init() {
	// Sort by suffix length descending so longest match wins on
	// every ReplaceAll pass. Stable order doesn't matter here because
	// distinct suffixes can't collide on length.
	sort.SliceStable(lifecycleSubstitutionRules, func(i, j int) bool {
		return len(lifecycleSubstitutionRules[i].suffix) > len(lifecycleSubstitutionRules[j].suffix)
	})
}

func (s *CronScheduler) dispatchAndRecord(ctx context.Context, ruleID string, entry *cronEntry, previousFiredNanos int64) {
	dispatchStart := time.Now()
	status := cronFireStatusSuccess

	defer func() {
		if r := recover(); r != nil {
			status = cronFireStatusPanic
			s.logger.Error("Cron rule fire panicked",
				"rule_id", ruleID,
				"panic", r)
		}
		// Single source of truth for fires_total + fire_duration: the
		// deferred block runs whether we exited normally or via panic,
		// so the counter and histogram always reflect the actual
		// outcome.
		s.metrics.recordFire(ruleID, status, time.Since(dispatchStart).Seconds())
	}()

	rule := entry.rule
	actions := rule.Actions() // already a clone — safe to iterate

	// ExecutionContext is intentionally sparse for cron fires: no entity,
	// no related entity, no MatchState. The Schedule shim supplies the
	// cron-specific `$schedule.*` namespace; SubstituteVariables in
	// execution_context.go also handles `$now` natively. The future
	// per-entity fan-out extension (Definition.ForEach) populates
	// EntityID / Entity / State per iteration alongside Schedule —
	// neither shim leaks into the other.
	var lastFired time.Time
	if previousFiredNanos > 0 {
		lastFired = time.Unix(0, previousFiredNanos).UTC()
	}
	ec := &ExecutionContext{
		Schedule: &ScheduleContext{
			ID:          ruleID,
			Spec:        rule.ScheduleString(),
			LastFiredAt: lastFired,
		},
	}

	dispatchedOK := true
	for i, action := range actions {
		if err := s.executor.Execute(ctx, action, ec); err != nil {
			if errors.Is(err, ErrDenyVerdict) {
				// Deny is terminal for the fire cycle: subsequent actions do not run.
				// "denied" is operator-distinct from "error" — "a rule said no" vs
				// "things are broken". Alerting on status="error" will not surface
				// denials; operators who want a unified "rule did not complete normally"
				// view must also include status="denied" in their queries.
				status = cronFireStatusDenied
				s.logger.Info("Cron rule action denied; short-circuiting remaining actions",
					"rule_id", ruleID,
					"action_index", i,
					"action_type", action.Type,
					"error", err)
				break
			}
			dispatchedOK = false
			s.logger.Warn("Cron rule action failed",
				"rule_id", ruleID,
				"action_index", i,
				"action_type", action.Type,
				"error", err)
			// Best-effort: continue to subsequent actions so one bad
			// publish doesn't block sibling triple writes etc.
		}
	}
	if !dispatchedOK && status != cronFireStatusDenied {
		status = cronFireStatusError
	}

	// Record last-fired timestamp only after dispatch — both in-memory
	// (cooldown gate) and persisted to RULE_SCHEDULES KV (cross-restart
	// missed-fire detection). Persistence failures are logged but do
	// not affect dispatch correctness; the next successful fire will
	// overwrite the record.
	firedAt := time.Now()
	entry.lastFiredNanos.Store(firedAt.UnixNano())
	s.metrics.recordNextFire(ruleID, float64(rule.Schedule().Next(firedAt).Unix()))

	if s.tracker != nil {
		// Best-effort persistence: the cooldown gate uses entry.lastFiredNanos
		// (in-memory), so KV unavailability is purely an observability
		// concern. Worst case across a restart: missed-fire detection thinks
		// the rule fired one tick earlier than it did → at most one stray
		// Warn log on next startup, no dispatch impact.
		if err := s.tracker.RecordFire(ctx, ruleID, rule.ScheduleString(), firedAt); err != nil {
			s.logger.Warn("Failed to persist cron rule fire timestamp",
				"rule_id", ruleID,
				"error", err)
		}
	}

	if dispatchedOK {
		s.logger.Debug("Cron rule fired",
			"rule_id", ruleID,
			"actions", len(actions))
	}
}

func collectProjectionActionObligations(
	definitions []Definition,
) ([]projectionActionObligation, error) {
	var obligations []projectionActionObligation
	for _, definition := range definitions {
		lists := []projectionActionList{
			{name: "on_enter", actions: definition.OnEnter},
			{name: "on_exit", actions: definition.OnExit},
			{name: "while_true", actions: definition.WhileTrue},
			{name: "on_recovery", actions: definition.OnRecovery},
			{name: "actions", actions: definition.Actions},
		}
		for _, list := range lists {
			for index, action := range list.actions {
				if action.Type != ActionTypeReconcilePredicates {
					continue
				}
				location := fmt.Sprintf("%s %s[%d]", definition.ID, list.name, index)
				if err := validateProjectionActionSelectors(action); err != nil {
					return nil, fmt.Errorf("%s: %w", location, err)
				}
				pattern, unresolved, err := inferProjectionActionPattern(definition, action)
				if err != nil {
					return nil, fmt.Errorf("%s: %w", location, err)
				}
				obligations = append(obligations, projectionActionObligation{
					contract:   action.ProjectionContract,
					group:      action.ProjectionGroup,
					predicate:  action.Predicate,
					pattern:    pattern,
					unresolved: unresolved,
					location:   location,
				})
			}
		}
	}
	sort.Slice(obligations, func(i, j int) bool {
		left, right := obligations[i], obligations[j]
		switch {
		case left.contract != right.contract:
			return left.contract < right.contract
		case left.group != right.group:
			return left.group < right.group
		case left.predicate != right.predicate:
			return left.predicate < right.predicate
		default:
			return left.location < right.location
		}
	})
	return obligations, nil
}

func cloneProjectionContracts(contracts []projection.Contract) []projection.Contract {
	if contracts == nil {
		return nil
	}
	copies := make([]projection.Contract, len(contracts))
	for i, contract := range contracts {
		copies[i] = contract
		copies[i].BirthPredicates = append([]string(nil), contract.BirthPredicates...)
		copies[i].Groups = make([]projection.PredicateGroup, len(contract.Groups))
		for j, group := range contract.Groups {
			copies[i].Groups[j] = group
			copies[i].Groups[j].Predicates = append([]string(nil), group.Predicates...)
		}
	}
	return copies
}

