func validateProjectionActionSelectors(action Action) error {
	if strings.TrimSpace(action.ProjectionContract) == "" {
		return fmt.Errorf("reconcile_predicates projection_contract is required")
	}
	if strings.TrimSpace(action.ProjectionGroup) == "" {
		return fmt.Errorf("reconcile_predicates projection_group is required")
	}
	if strings.TrimSpace(action.Predicate) == "" {
		return fmt.Errorf("reconcile_predicates predicate is required")
	}
	if strings.Contains(action.Predicate, "$") {
		return fmt.Errorf("reconcile_predicates predicate %q must be a literal", action.Predicate)
	}
	return nil
}

func buildPairKey(entityID1, entityID2 string) string {
	if entityID1 < entityID2 {
		return entityID1 + "_" + entityID2
	}
	return entityID2 + "_" + entityID1
}

func (st *StateTracker) Delete(ctx context.Context, ruleID, entityKey string) error {
	// Handle nil bucket (for tests)
	if st.bucket == nil {
		return fmt.Errorf("state tracker bucket is nil")
	}

	key := buildStateKey(ruleID, entityKey)

	err := st.bucket.Delete(ctx, key)
	if err != nil && !errors.Is(err, jetstream.ErrKeyNotFound) {
		return fmt.Errorf("delete rule state: %w", err)
	}

	return nil
}

type CronSchedulerConfig struct {
	// Executor is required. A nil executor is rejected because every
	// fire would silently no-op, hiding misconfiguration.
	Executor ActionExecutorInterface

	// Tracker is optional. Pass nil to run without persistence — no
	// cross-restart missed-fire detection, no cooldown hydration on
	// startup. Tests typically pass nil; the production processor
	// wires in a tracker bound to the RULE_SCHEDULES bucket.
	Tracker *ScheduleTracker

	// Metrics is optional. Pass nil to run without Prometheus
	// observability — every recordX call short-circuits on the nil
	// receiver. Tests that don't assert on metrics pass nil; the
	// production processor wires in metrics scoped to its registry.
	Metrics *cronMetrics

	// Logger is optional. Defaults to slog.Default() when nil so the
	// scheduler always has something to log to.
	Logger *slog.Logger

	// Ready is an optional fail-closed dispatch gate. Production binds it to
	// the Processor's authoritative graph-state guard; tests may omit it.
	Ready func() bool
}

func deriveEffectiveProjectionContracts(
	definitions []Definition,
	declared []projection.Contract,
) ([]projection.Contract, error) {
	obligations, err := collectProjectionActionObligations(definitions)
	if err != nil {
		return nil, err
	}
	if declared != nil {
		effective := cloneProjectionContracts(declared)
		if err := validateDeclaredProjectionSuperset(effective, obligations); err != nil {
			return nil, err
		}
		return effective, nil
	}
	if len(obligations) == 0 {
		return nil, nil
	}
	return buildMinimalProjectionContracts(obligations)
}

func scheduleKey(ruleID string) string {
	return ruleID
}

func applyMessageSubstitutions(template string, data map[string]any) string {
	if len(data) == 0 {
		return template
	}
	return messageTokenRe.ReplaceAllStringFunc(template, func(token string) string {
		// token shape: "$message.<dotted.path>"
		path := strings.TrimPrefix(token, "$message.")
		if path == "" {
			return token
		}
		value, ok := expression.ExtractMessageValue(expression.MessageFields(data), path)
		if !ok {
			return token
		}
		return fmt.Sprintf("%v", value)
	})
}

type StatefulEvaluator struct {
	stateTracker   *StateTracker
	actionExecutor ActionExecutorInterface
	exprEvaluator  *expression.Evaluator
	logger         *slog.Logger

	// lifecycleManager is the optional pkg/lifecycle.Manager wired by
	// the rule Processor at Initialize. When non-nil, runEvaluation
	// pre-resolves the trigger entity's lifecycle state into the
	// evaluator's stateFields map so condition.Field references like
	// `$entity.lifecycle.phase` evaluate. The action layer reads via
	// ActionExecutor.lifecycle independently.
	lifecycleManager LifecycleManager

	// metrics is the optional rule-processor Metrics instance wired by
	// SetMetrics. nil (test constructions that don't call SetMetrics,
	// or a metrics-less deployment) makes runActions' failure-counting
	// a no-op — never a nil-deref.
	metrics *Metrics
}

func (s *CronScheduler) Register(rule *CronRule) error {
	if rule == nil {
		return errors.New("cron scheduler: nil rule")
	}
	s.lifecycleMu.Lock()
	if s.registerFence {
		s.lifecycleMu.Unlock()
		return errors.New("cron scheduler: registration admission is closed")
	}
	if !rule.Enabled() {
		s.lifecycleMu.Unlock()
		s.logger.Debug("Skipping disabled cron rule", "rule_id", rule.ID())
		return nil
	}

	s.mu.Lock()
	if _, exists := s.entries[rule.ID()]; exists {
		s.mu.Unlock()
		s.lifecycleMu.Unlock()
		return fmt.Errorf("cron rule %s already registered", rule.ID())
	}

	entry := &cronEntry{rule: rule}
	ruleID := rule.ID() // captured by closure; rule is stable for the entry's lifetime

	job := cronlib.FuncJob(func() {
		s.fire(ruleID)
	})

	entry.entryID = s.cron.Schedule(rule.Schedule(), job)
	s.entries[ruleID] = entry
	s.mu.Unlock()
	s.lifecycleMu.Unlock()

	s.metrics.recordRuleRegistered()
	s.metrics.recordNextFire(ruleID, float64(rule.Schedule().Next(time.Now()).Unix()))

	s.logger.Info("Cron rule registered",
		"rule_id", ruleID,
		"schedule", rule.ScheduleString(),
		"action_count", len(rule.Actions()))
	return nil
}

func hasTransitionConditions(ruleDef Definition) bool {
	for _, cond := range ruleDef.Conditions {
