func (e *StatefulEvaluator) runActions(
	ctx context.Context,
	ruleDef Definition,
	ec *ExecutionContext,
	actions []Action,
	entity *gtypes.EntityState,
	stateFields expression.StateFields,
	messageFields expression.MessageFields,
	entityID, relatedID string,
) {
	for _, action := range actions {
		if len(action.When) > 0 {
			match, whenErr := e.evaluateWhen(ctx, action.When, entity, stateFields, messageFields)
			if whenErr != nil {
				e.logger.Warn("When clause evaluation failed, skipping action",
					"rule_id", ruleDef.ID,
					"entity_id", entityID,
					"action_type", action.Type,
					"error", whenErr)
				continue
			}
			if !match {
				e.logger.Debug("Action skipped by When clause",
					"rule_id", ruleDef.ID,
					"entity_id", entityID,
					"action_type", action.Type)
				continue
			}
		}

		// Per-action firing-cap gate. Look up the action's stable
		// identifier (author-supplied Action.ID or deterministic hash),
		// compare against the resolved cap (effective default 3 when
		// unset; 0 = unlimited per operator opt-out), and skip the
		// action when it has already fired up to its cap. Counter
		// state lives on ec.State.ActionIterations and is persisted
		// to the StateTracker after runActions returns.
		if ec.State != nil {
			actionID := action.effectiveID(ruleDef.ID)
			maxIter, fromDefault := action.effectiveMaxIterations()
			fired := ec.State.ActionIterations[actionID]
			if !isUnlimited(maxIter) && fired >= maxIter {
				e.logger.Warn("Action firing cap reached, skipping",
					"rule_id", ruleDef.ID,
					"entity_id", entityID,
					"action_type", action.Type,
					"action_id", actionID,
					"fired", fired,
					"cap", maxIter,
					"cap_source", capSource(fromDefault))
				continue
			}
			if ec.State.ActionIterations == nil {
				ec.State.ActionIterations = map[string]int{}
			}
			ec.State.ActionIterations[actionID] = fired + 1
		}

		if err := e.actionExecutor.Execute(ctx, action, ec); err != nil {
			if errors.Is(err, ErrDenyVerdict) {
				// Deny is terminal: subsequent actions in this evaluation cycle do not
				// run. Non-deny errors continue best-effort dispatch (see else branch).
				e.logger.Info("rule action denied; short-circuiting remaining actions",
					"rule_id", ruleDef.ID,
					"entity_id", entityID,
					"action_type", action.Type,
					"error", err)
				break
			}
			e.logger.Error("Failed to execute action",
				"rule_id", ruleDef.ID,
				"entity_id", entityID,
				"related_id", relatedID,
				"action_type", action.Type,
				"error", err)
			// Every non-deny action-execution failure is otherwise only a
			// log line — a fail-closed action (e.g. publish_agent rejecting
			// a non-integer loop_max_iterations) is exactly the silent-
			// failure class this repo hunts if nothing alerts on it.
			if e.metrics != nil {
				e.metrics.actionFailuresTotal.WithLabelValues(action.Type).Inc()
			}
		}
	}
}

type MatchState struct {
	RuleID         string    `json:"rule_id"`
	EntityKey      string    `json:"entity_key"`
	IsMatching     bool      `json:"is_matching"`
	LastTransition string    `json:"last_transition"` // ""|"entered"|"exited"
	TransitionAt   time.Time `json:"transition_at,omitempty"`
	SourceRevision uint64    `json:"source_revision"`
	LastChecked    time.Time `json:"last_checked"`

	// Iteration tracks how many times this rule has entered the matching state
	// for this entity. Incremented on each TransitionEntered, preserved through exits.
	Iteration int `json:"iteration"`

	// MaxIterations is the configured limit from the rule Definition.
	// 0 means no limit. Used with $state.iteration in When clauses for retry budgets.
	MaxIterations int `json:"max_iterations,omitempty"`

	// FieldValues tracks the last-seen values of fields used in transition conditions.
	// Keys are field names (e.g., "workflow.plan.status"), values are the string
	// representation of the last observed value. Used by the transition operator
	// to detect field-level state changes across evaluations.
	FieldValues map[string]string `json:"field_values,omitempty"`

	// ActionIterations tracks per-action firing counts for the
	// Action.MaxIterations cap. Keys are Action.effectiveID(rule_id) —
	// either the author's explicit Action.ID or the deterministic hash
	// of (rule_id, action_type, subject_or_predicate, role). Counts
	// persist across rule entries/exits so the cap covers the entire
	// match-cycle for an entity, not just one transition.
	//
	// When an action's effectiveID isn't yet a key in this map, its
	// count is treated as 0 (unfired). The first fire writes the entry.
	ActionIterations map[string]int `json:"action_iterations,omitempty"`
}

func shouldFireOnRecovery(ruleDef Definition) bool {
	if len(ruleDef.OnRecovery) > 0 {
		return true
	}
	return ruleDef.RerunOnRecovery && len(ruleDef.OnEnter) > 0
}

